"""
Prediction module for Cancer Survival Analysis.

Transforms single patient records, computes predicted risk scores,
categorizes patients into high/low risk strata, evaluates milestone survival
probabilities (12, 24, 36, 60 months), and generates feature attributions.
"""

from typing import Any, Dict, List, Optional, Union
import numpy as np
import pandas as pd

from ml.preprocessing import preprocess_single_patient
from ml.explainability import get_local_explanation

CLINICAL_DISCLAIMER: str = (
    "CLINICAL DISCLAIMER: This risk prediction is generated by an educational and "
    "research machine learning model trained on synthetic cancer survival data. "
    "It is NOT validated for clinical diagnosis, treatment decisions, or patient prognosis. "
    "Always consult a board-certified oncologist or medical professional for health guidance."
)

SURVIVAL_MILESTONES: List[int] = [12, 24, 36, 60]


def _evaluate_survival_step_function(fn: Any, time_point: float) -> float:
    """
    Safely evaluate a scikit-survival StepFunction at a specific time milestone.

    Parameters
    ----------
    fn : sksurv.functions.StepFunction or callable
        StepFunction representing S(t).
    time_point : float
        Evaluation time in months.

    Returns
    -------
    float
        Estimated survival probability in [0.0, 1.0].
    """
    try:
        prob = float(fn(time_point))
    except Exception:
        # Step function might raise error if time_point is outside [min(x), max(x)]
        if hasattr(fn, "x") and hasattr(fn, "y") and len(fn.x) > 0:
            if time_point < fn.x[0]:
                prob = 1.0
            else:
                prob = float(fn.y[-1])
        else:
            prob = 0.5

    return max(0.0, min(1.0, prob))


def predict_risk(
    patient_data: Union[Dict[str, Any], pd.Series, pd.DataFrame],
    models: Dict[str, Any],
    model_name: str = "rsf",
) -> Dict[str, Any]:
    """
    Predict cancer survival risk score, category, milestone survival probabilities,
    and feature attributions for a single patient.

    Parameters
    ----------
    patient_data : dict, pd.Series, or pd.DataFrame
        Patient features including 'age', 'tumor_stage', 'gene_expr_A',
        'gene_expr_B', 'gene_expr_C', 'methylation_A', 'methylation_B'.
    models : dict
        Loaded models dictionary containing 'rsf', 'cox_ph', 'preprocessor_info',
        and 'metadata'.
    model_name : str, default='rsf'
        Selected model identifier ('rsf' or 'cox_ph').

    Returns
    -------
    dict
        Prediction results including risk score, category (High/Low),
        threshold, survival probabilities at 12, 24, 36, 60 months,
        local feature contributions, and disclaimer.

    Raises
    ------
    KeyError
        If requested model or preprocessor is not present in models dict.
    """
    if model_name not in models:
        raise KeyError(
            f"Model '{model_name}' not found in loaded models. Available: {list(models.keys())}"
        )
    if "preprocessor_info" not in models:
        raise KeyError("models dictionary must contain 'preprocessor_info'.")

    model = models[model_name]
    preprocessor_info = models["preprocessor_info"]
    metadata = models.get("metadata", {})

    # 1. Preprocess patient data
    X_patient = preprocess_single_patient(patient_data, preprocessor_info)

    # 2. Compute risk score
    # In sksurv, higher predict() output indicates higher mortality risk
    risk_score = float(model.predict(X_patient)[0])

    # 3. Determine risk category using established training threshold
    thresholds = metadata.get("thresholds", {})
    threshold = float(thresholds.get(model_name, metadata.get("risk_threshold", 0.0)))

    risk_category = "High Risk" if risk_score >= threshold else "Low Risk"

    # 4. Evaluate survival probabilities at milestone months (12, 24, 36, 60)
    survival_probabilities: Dict[str, float] = {}
    survival_timeline: List[Dict[str, Any]] = []

    if hasattr(model, "predict_survival_function"):
        try:
            surv_funcs = model.predict_survival_function(X_patient)
            fn = surv_funcs[0]

            for m in SURVIVAL_MILESTONES:
                prob = _evaluate_survival_step_function(fn, float(m))
                survival_probabilities[str(m)] = round(prob, 4)
                survival_timeline.append({
                    "month": m,
                    "probability": round(prob, 4),
                    "percentage": round(prob * 100, 1),
                })
        except Exception:
            survival_probabilities = {}
            survival_timeline = []

    # 5. Compute local feature explanations
    try:
        explanation = get_local_explanation(
            patient_data=X_patient,
            model=model,
            preprocessor_info=preprocessor_info,
            model_name=model_name,
        )
        attribs = explanation.get("feature_attributions", [])
        feature_contributions = {a["feature"]: a["contribution"] for a in attribs}
    except Exception:
        feature_contributions = {}

    # Build explanation text
    explanation_text = (
        f"<strong>Model:</strong> {'Random Survival Forest' if model_name == 'rsf' else 'Cox Proportional Hazards'}<br>"
        f"<strong>Risk Score:</strong> {round(risk_score, 4)} "
        f"({'above' if risk_score >= threshold else 'below'} threshold of {round(threshold, 4)})<br>"
        f"<strong>Interpretation:</strong> A higher risk score indicates higher predicted mortality "
        f"hazard relative to other cohort patients. "
        f"The threshold corresponds to the median training cohort risk score."
    )

    # Format patient input for response echo
    if isinstance(patient_data, dict):
        patient_echo = patient_data
    elif isinstance(patient_data, pd.DataFrame):
        patient_echo = patient_data.iloc[0].to_dict()
    else:
        patient_echo = patient_data.to_dict() if hasattr(patient_data, 'to_dict') else {}

    return {
        "status": "success",
        "model_name": model_name,
        "risk_score": round(risk_score, 4),
        "risk_category": risk_category,
        "threshold": round(threshold, 4),
        "relative_to_threshold": "above" if risk_score >= threshold else "below",
        "survival_probabilities": survival_probabilities,
        "survival_timeline": survival_timeline,
        "feature_contributions": feature_contributions,
        "explanation": explanation_text,
        "patient_features": patient_echo,
        "disclaimer": CLINICAL_DISCLAIMER,
    }


def get_model_info(models: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract and return model metadata, feature names, performance metrics,
    and clinical descriptions.

    Parameters
    ----------
    models : dict
        Loaded models dictionary containing 'preprocessor_info' and 'metadata'.

    Returns
    -------
    dict
        Model metadata report.
    """
    metadata = models.get("metadata", {})
    preprocessor_info = models.get("preprocessor_info", {})

    return {
        "training_date": metadata.get("training_date", "Unknown"),
        "best_model": metadata.get("best_model", "rsf"),
        "best_c_index": metadata.get("best_c_index", None),
        "risk_threshold": metadata.get("risk_threshold", None),
        "thresholds": metadata.get("thresholds", {}),
        "metrics": metadata.get("metrics", {}),
        "feature_names": preprocessor_info.get("feature_names", metadata.get("feature_names", [])),
        "numeric_features": preprocessor_info.get("numeric_features", []),
        "categorical_features": preprocessor_info.get("categorical_features", []),
        "dataset_statistics": metadata.get("dataset_statistics", {}),
        "model_hyperparameters": metadata.get("model_hyperparameters", {}),
        "disclaimer": CLINICAL_DISCLAIMER,
    }
